class Brief(BaseModel):
    """
    Structured brief the Director extracts from intake (PRD 7.1 FR-INT-03, FR-INT-04, FR-INT-05). Every field is an editable chip; empty arrays are allowed, missing keys are not.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    goal: Annotated[str, Field(max_length=500, min_length=1)]
    deliverables: Annotated[list[BriefDeliverable], Field(max_length=10, min_length=1)]
    audience: Annotated[str, Field(max_length=200, min_length=1)]
