    """
    Due date, or null when the task has none.
    """
    constraints: Annotated[list[Constraint], Field(max_length=20)]
    sources: Annotated[list[BriefSource], Field(max_length=50)]
    sensitivity: DataClass
    """
    Most sensitive class of data the task touches (PRD 12.1 data classes; ADR-0002).
    """
    assumptions: Annotated[list[BriefAssumption], Field(max_length=10)]
    """
    FR-INT-04: what was assumed instead of asking, shown as "Assumed: ...".
    """
    applied_preferences: Annotated[list[BriefAppliedPreference], Field(max_length=20)]
    """
    FR-INT-05: preferences and past answers applied from memory instead of asking, each with its citation.
    """


