class Card(BaseModel):
    """
    One card, every channel (PRD 10.2, 10.3): needs-you, gate, consent and meeting cards. Channel rules are data: answer_channels is limited per kind (email answers questions only; gates need sign-in on the web or a verified WhatsApp number; consent needs the web). safe_default is the option id applied at timeout, which must be one of the options; a gate's is always hold, so a gate never times out to go.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    id: Ulid
    world_id: WorldId
    run_id: RunId
    kind: Literal["needs_you", "gate", "consent", "meeting"]
    rung: Literal["needs_you", "blocked", "meeting", "gate", "consent"]
    """
    Escalation ladder rung (PRD 10.2); needs_you cards may be blocked.
    """
    header: CardHeader
    what_happened: Annotated[str, Field(max_length=140, min_length=1)]
    why_it_matters: Annotated[str, Field(max_length=280, min_length=1)]
    options: CardOptions
    add_context: bool
    """
    Whether the card offers the add-context field.
    """
    actions: list[Literal["show_me", "snooze", "delegate"]]
    answer_channels: Annotated[list[Channel], Field(min_length=1)]
    created_at: Timestamp
    timeout: Annotated[int, Field(ge=1)]
    """
    Seconds after created_at when the safe default applies and the Director posts a Nudge.
    """
    safe_default: CardOptionId
    gate: CardGate | None
    """
    Set on gate cards only.
    """
    consent: CardConsent | None
    """
    Set on consent cards only.
    """


